"""Combine independent blinded ratings for the fixed visual protocol."""

from collections import Counter, defaultdict
import json
from pathlib import Path


FIELDS = "USLRABC"
COARSE = "USLR"
ORDERED = "SABC"
HERE = Path(__file__).resolve().parent / "protocol"


def read_ratings(path):
    rows = {}
    for line in path.read_text().splitlines():
        code, ratings, shafts, apertures, *notes = line.split(maxsplit=4)
        if code in rows or len(ratings) != len(FIELDS) or any(flag not in "YN?" for flag in ratings):
            raise ValueError(f"Invalid or duplicated rating: {line}")
        if {shafts, apertures} - {"0", "1", "2", "3+", "?"}:
            raise ValueError(f"Invalid motif count: {line}")
        rows[code] = {
            "flags": ratings,
            "shaft_count": shafts,
            "aperture_count": apertures,
            "note": " ".join(notes),
        }
    return rows


def status(flags, subset):
    values = [flags[field] for field in subset]
    if all(value == "Y" for value in values):
        return "yes"
    if "N" in values:
        return "no"
    return "unresolved"


def main():
    key = json.loads((HERE / "key.json").read_text())
    first, second = (read_ratings(HERE / f"reader{i}.tsv") for i in (1, 2))
    valid_codes = {row["code"] for row in key}
    if set(first) != valid_codes or set(second) != valid_codes:
        raise ValueError("Ratings do not match the frozen specimen codes")
    groups = defaultdict(lambda: {"n": 0, "coarse": Counter(), "ordered": Counter()})
    reliability = defaultdict(Counter)
    joined = []
    for item in key:
        code = item["code"]
        ratings = (first[code], second[code])
        agreed = {}
        for field, left, right in zip(FIELDS, ratings[0]["flags"], ratings[1]["flags"]):
            agreed[field] = left if left == right else "?"
            if "?" in (left, right):
                reliability[field]["one_or_both_uncertain"] += 1
            elif left == right:
                reliability[field]["resolved_agreement"] += 1
            else:
                reliability[field]["resolved_disagreement"] += 1
        coarse, ordered = status(agreed, COARSE), status(agreed, ORDERED)
        data = dict(item, reader1=ratings[0], reader2=ratings[1], consensus=agreed, coarse=coarse, ordered=ordered)
        joined.append(data)
        group = groups[item["tradition"] + "/" + item["role"]]
        group["n"] += 1
        group["coarse"][coarse] += 1
        group["ordered"][ordered] += 1

    total_agreement = Counter()
    for field in FIELDS:
        total_agreement.update(reliability[field])
    output = {
        "rating_order": FIELDS,
        "specimens": joined,
        "group_results": groups,
        "agreement_by_feature": reliability,
        "all_ratings_agreement": total_agreement,
    }
    (HERE / "reader-comparison.json").write_text(json.dumps(output, indent=2) + "\n")


if __name__ == "__main__":
    main()
